const CLASSES=['Bárbaro','Bardo','Bruxo','Clérigo','Druida','Feiticeiro','Guerreiro','Ladino','Mago','Monge','Paladino','Patrulheiro'];
const ATTR=['Força','Destreza','Constituição','Inteligência','Sabedoria','Carisma'];
const SKILLS=[['Acrobacia',1],['Arcanismo',3],['Atletismo',0],['Atuação',5],['Enganação',5],['Furtividade',1],['História',3],['Intimidação',5],['Intuição',4],['Investigação',3],['Lidar com Animais',4],['Medicina',4],['Natureza',3],['Percepção',4],['Persuasão',5],['Prestidigitação',1],['Religião',3],['Sobrevivência',4]];
const TABS=['Visão geral','Combate','Magias','Equipamento','História','Catálogo','Criar ficha'];
let db;try{db=JSON.parse(localStorage.getItem('codice2024')||'null')}catch{}if(!db||!Array.isArray(db.chars))db={chars:[],selected:null};let tab=0;
function fresh(name='Novo aventureiro',cls='Guerreiro',level=1){return{id:crypto.randomUUID(),name,cls,level,species:'',background:'',subclass:'',attrs:[10,10,10,10,10,10],skills:{},saves:[],hp:10,maxhp:10,temp:0,ac:10,speed:30,inspiration:false,deathSuccess:0,deathFail:0,notes:'',features:'',equipment:'',bio:'',money:0,spellAttr:3,slots:Array(9).fill(0),used:Array(9).fill(0),spellnotes:'',attacks:[],conditions:'',resource:''}}
function c(){return db.chars.find(x=>x.id===db.selected)}function esc(x){return String(x??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}function mod(x){return Math.floor((x-10)/2)}function signed(x){return x>=0?'+'+x:x}function pb(){return 2+Math.floor((c().level-1)/4)}
function save(){try{localStorage.setItem('codice2024',JSON.stringify(db,function(k,v){return k==='data'&&this.storageKey?undefined:v;}));document.querySelector('#saved').textContent='Tudo salvo';window.backupCodiceWeb?.()}catch{toast('Não foi possível salvar. Exporte um backup.')}}
function set(k,v){c()[k]=v;save();if(!['notes','features','equipment','bio','spellnotes','resource','conditions'].includes(k))render()}
function field(label,key,type='text'){return `<label>${label}<input type="${type}" value="${esc(c()[key])}" onchange="set('${key}',this.type==='number'?Number(this.value):this.value)"></label>`}function area(label,key){return `<label>${label}<textarea oninput="set('${key}',this.value)">${esc(c()[key])}</textarea></label>`}
function toast(s){let el=document.querySelector('#toast');el.textContent=s;el.style.display='block';setTimeout(()=>el.style.display='none',2800)}
function render(){document.querySelector('#characters').innerHTML=db.chars.map(x=>`<button class="char ${x.id===db.selected?'active':''}" onclick="selectChar('${x.id}')">✧ ${esc(x.name)}<small>${esc(x.cls)} · Nível ${x.level}</small></button>`).join('');let x=c();document.querySelector('#tabs').innerHTML=x?TABS.map((t,i)=>`<button class="${tab===i?'active':''}" onclick="switchTab(${i})">${t}</button>`).join(''):'';document.querySelector('#title').textContent=x?.name||'Sua próxima aventura';document.querySelector('#subtitle').textContent=x?`${x.species||'Espécie a escolher'} · ${x.cls}${x.subclass?' / '+x.subclass:''}`:'Um lugar para guardar suas histórias, escolhas e conquistas.';document.querySelector('#levelBadge').textContent=x?'NÍVEL '+x.level:'COMECE AQUI';document.querySelector('#view').innerHTML=x?(tab===5?catalogView():tab===6?builderView():[overview,combat,magic,gear,story][tab]()):`<section class="card"><h2>Uma nova história espera por você.</h2><p>Crie uma ficha em branco. Seus personagens ficam salvos neste navegador, sem assinatura.</p><button class="primary" onclick="create()">＋ Criar meu primeiro personagem</button></section>`}
function selectChar(id){db.selected=id;save();render()}
function overview(){let x=c();return `<div class="stats">${ATTR.map((a,i)=>`<div class="stat"><label>${a.toUpperCase()}</label><b>${signed(mod(x.attrs[i]))}</b><input aria-label="${a}" type="number" min="1" max="30" value="${x.attrs[i]}" onchange="c().attrs[${i}]=Math.max(1,Math.min(30,Number(this.value)));save();render()"></div>`).join('')}</div><div class="grid"><section class="card"><h3>Essenciais</h3><div class="row"><span>Bônus de proficiência</span><b class="big">${signed(pb())}</b></div><div class="row"><span>Iniciativa</span><b>${signed(mod(x.attrs[1]))}</b></div><div class="row"><span>Percepção passiva</span><b>${10+mod(x.attrs[4])+(x.skills[13]||0)*pb()}</b></div><div class="row"><label>Inspiração Heroica</label><input aria-label="Inspiração Heroica" type="checkbox" ${x.inspiration?'checked':''} onchange="set('inspiration',this.checked)"></div></section><section class="card"><h3>Salvaguardas</h3>${ATTR.map((a,i)=>`<div class="skill"><input aria-label="Proficiência em ${a}" type="checkbox" ${x.saves.includes(i)?'checked':''} onchange="c().saves=this.checked?[...c().saves,${i}]:c().saves.filter(v=>v!==${i});save();render()"><span>${a}</span><b>${signed(mod(x.attrs[i])+(x.saves.includes(i)?pb():0))}</b></div>`).join('')}</section><section class="card highlight"><h3>Pontos de vida</h3><div class="big">${x.hp} <span class="muted">/ ${x.maxhp}</span></div>${field('PV máximos','maxhp','number')}${field('PV temporários','temp','number')}<div class="row"><input id="hpdelta" aria-label="Quantidade de pontos de vida" type="number" min="0" placeholder="Valor"><button onclick="changeHP(-1)">Dano</button><button onclick="changeHP(1)">Curar</button></div></section><section class="card wide"><h3>Perícias</h3><p class="muted">Escolha proficiência ou especialização em cada perícia.</p>${SKILLS.map(([s,a],i)=>`<div class="skill"><b>${signed(mod(x.attrs[a])+(x.skills[i]||0)*pb())}</b><span>${s}</span><select aria-label="Proficiência: ${s}" onchange="c().skills[${i}]=Number(this.value);save();render()">${['Nenhuma','Proficiente','Especialista'].map((n,j)=>`<option value="${j}" ${Number(x.skills[i]||0)===j?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}</section><section class="card"><h3>Identidade</h3>${field('Nome','name')}<label>Classe<select onchange="set('cls',this.value)">${CLASSES.map(s=>`<option ${x.cls===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Nível<input type="number" min="1" max="20" value="${x.level}" onchange="set('level',Math.max(1,Math.min(20,Number(this.value))))"></label>${field('Subclasse','subclass')}${field('Espécie','species')}${field('Antecedente','background')}<p class="muted">Escolhas e progressão de classe são manuais. Subir o nível atualiza o bônus de proficiência.</p></section></div>`}
function changeHP(sign){let n=Math.max(0,Number(document.querySelector('#hpdelta').value)||0),x=c();if(sign<0){let t=Math.min(x.temp,n);x.temp-=t;x.hp=Math.max(0,x.hp-(n-t))}else x.hp=Math.min(x.maxhp,x.hp+n);save();render()}
function combat(){let x=c();return `<div class="grid"><section class="card">${field('Classe de Armadura','ac','number')}${field('Deslocamento (pés)','speed','number')}${field('Condições atuais','conditions')}<h3>Salvaguardas contra a morte</h3>${['deathSuccess','deathFail'].map((k,j)=>`<div class="row"><span>${j?'Falhas':'Sucessos'}</span>${[1,2,3].map(n=>`<input type="checkbox" aria-label="${j?'Falha':'Sucesso'} ${n}" ${x[k]>=n?'checked':''} onchange="set('${k}',this.checked?${n}:${n-1})">`).join('')}</div>`).join('')}</section><section class="card wide"><h3>Ataques</h3><p class="muted">Registre bônus final, dano e maestria conforme suas escolhas.</p>${x.attacks.map((a,i)=>`<div class="card manual-attack-card" data-manual-attack="${a.id}">${typeof attackMediaView==='function'?attackMediaView('manual:'+a.id):''}<b>${esc(a.name)}</b><div class="row"><span>Ataque ${esc(a.bonus)} · ${esc(a.damage)}</span><button onclick="roll(20,Number(c().attacks[${i}].bonus)||0)">Rolar ataque</button><button class="danger" onclick="c().attacks.splice(${i},1);save();render()">Remover</button></div><span class="muted">${esc(a.mastery)}</span></div>`).join('')}<label>Arma ou ataque<input id="an"></label><div class="row"><label>Bônus final<input type="number" id="ab" value="0"></label><label>Dano<input id="ad" placeholder="1d8 + 3 cortante"></label></div><label>Maestria / observações<input id="am" placeholder="Vex, Nick, Topple…"></label><button onclick="addAttack()">＋ Adicionar ataque</button></section><section class="card wide">${area('Características e talentos','features')}</section><section class="card">${area('Recursos de classe e dados de vida','resource')}<button onclick="rest()">Descanso longo</button><p class="muted">Restaura PV, espaços marcados e zera salvaguardas contra a morte. Outros recursos são manuais.</p><h3>Dados rápidos</h3>${[4,6,8,10,12,20,100].map(d=>`<button onclick="roll(${d},0)">d${d}</button>`).join(' ')}</section></div>`}
function addAttack(){let n=document.querySelector('#an').value.trim();if(!n)return toast('Informe o nome do ataque.');c().attacks.push({name:n,bonus:document.querySelector('#ab').value,damage:document.querySelector('#ad').value,mastery:document.querySelector('#am').value});save();render()}
function roll(d,b){let a=new Uint32Array(1);crypto.getRandomValues(a);let n=a[0]%d+1;toast(`d${d}: ${n}${b?' '+signed(b):''} = ${n+b}`)}function rest(){let x=c();x.hp=x.maxhp;x.temp=0;x.used=Array(9).fill(0);x.deathSuccess=x.deathFail=0;save();render();toast('Descanso longo registrado. Revise seus outros recursos.')}
function magic(){let x=c(),m=mod(x.attrs[x.spellAttr]);return `<div class="grid"><section class="card"><h3>Conjuração</h3><label>Atributo de conjuração<select onchange="set('spellAttr',Number(this.value))">${ATTR.map((a,i)=>`<option value="${i}" ${x.spellAttr===i?'selected':''}>${a}</option>`).join('')}</select></label><div class="row"><span>CD de salvaguarda</span><b class="big">${8+pb()+m}</b></div><div class="row"><span>Ataque de magia</span><b class="big">${signed(pb()+m)}</b></div><p class="muted">CD = 8 + proficiência + atributo. Bônus de itens e efeitos devem ser anotados abaixo.</p></section><section class="card wide"><h3>Espaços de magia</h3><p class="muted">Defina seus espaços máximos. Marque os espaços gastos. Magia de Pacto deve ser anotada separadamente.</p>${x.slots.map((v,i)=>v>0?`<div class="row"><span>${i+1}º círculo</span><input aria-label="Espaços máximos círculo ${i+1}" type="number" min="0" max="10" value="${v}" onchange="c().slots[${i}]=Math.max(0,Math.min(10,Number(this.value)));c().used[${i}]=Math.min(c().used[${i}],c().slots[${i}]);save();render()"><span class="slot">${Array.from({length:v},(_,j)=>`<input type="checkbox" aria-label="Espaço gasto ${j+1} círculo ${i+1}" ${x.used[i]>j?'checked':''} onchange="c().used[${i}]=this.checked?${j+1}:${j};save();render()">`).join('')}</span></div>`:'').join('')}${x.slots.some(v=>v>0)?'':'<p class="muted">Sem espaços de conjuração disponíveis para estas classes.</p>'}</section><section class="card full">${area('Grimório · truques, magias preparadas e descrições','spellnotes')}<a href="https://www.dndbeyond.com/sources/dnd/free-rules/spell-descriptions" target="_blank" rel="noopener">Consultar magias nas regras gratuitas oficiais ↗</a></section></div>`}
function gear(){return `<div class="grid"><section class="card wide">${area('Inventário · itens, quantidades e pesos','equipment')}</section><section class="card"><h3>Tesouro</h3><p>As moedas ficam na barra acima das abas. Registre recipientes e outros objetos de valor no inventário.</p></section></div>`}
function story(){return `<div class="grid"><section class="card wide">${area('História, aparência e vínculos','bio')}</section><section class="card">${area('Diário de aventuras','notes')}<button class="danger" onclick="removeChar()">Excluir personagem</button></section></div>`}
function create(){document.querySelector('#newclass').innerHTML=CLASSES.map(s=>`<option>${s}</option>`).join('');document.querySelector('#modal').showModal()}
document.querySelector('#confirm').onclick=e=>{if(!document.querySelector('#newname').value.trim())return;let x=fresh(document.querySelector('#newname').value.trim(),document.querySelector('#newclass').value,Math.max(1,Math.min(20,Number(document.querySelector('#newlevel').value)||1)));db.chars.push(x);db.selected=x.id;tab=0;save();render()};function removeChar(){if(confirm('Excluir esta ficha? Exporte um backup antes, se quiser guardá-la.')){db.chars=db.chars.filter(x=>x.id!==db.selected);db.selected=db.chars[0]?.id;save();render()}}
function exportChar(){if(!c())return toast('Crie um personagem primeiro.');let a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(c(),null,2)],{type:'application/json'}));a.href=u;a.download='personagem-2024.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.querySelector('#import').onchange=async e=>{try{let x=JSON.parse(await e.target.files[0].text());if(typeof x.name!=='string'||!Array.isArray(x.attrs)||x.attrs.length!==6||!x.attrs.every(n=>Number.isFinite(n)&&n>=1&&n<=30))throw Error();let n={...fresh(),...x,id:crypto.randomUUID()};n.classes=x.classes||[{name:x.cls,level:x.level,third:false}];n.calc=x.calc||{hp:false,slots:false};if(!Array.isArray(n.classes)||!n.classes.length||n.classes.length>12||n.classes.some(p=>!CLASSES.includes(p.name)||!Number.isInteger(p.level)||p.level<1)||new Set(n.classes.map(p=>p.name)).size!==n.classes.length||n.classes.reduce((a,p)=>a+p.level,0)>20||!Number.isInteger(n.level)||n.level<1||n.level>20||!Array.isArray(n.attacks)||!Array.isArray(n.saves)||!Array.isArray(n.slots)||n.slots.length!==9||!n.slots.every(v=>Number.isInteger(v)&&v>=0&&v<=10)||!Array.isArray(n.used)||n.used.length!==9)throw Error();if(typeof prepareRollGifImport512==='function')await prepareRollGifImport512(n);db.chars.push(n);db.selected=n.id;save();render();toast('Ficha importada.')}catch{toast('Arquivo inválido. Importe um JSON exportado pelo Códice.')}e.target.value=''};
render();
// Integração Android: exportação nativa e impressão do sistema.

exportChar=function(){if(!c())return toast('Crie um personagem primeiro.');CodiceAndroid.exportJson(JSON.stringify(c(),null,2));};
